import{_ as t,c as a,a0 as r,o}from"./chunks/framework.BGabeMLJ.js";const p=JSON.parse('{"title":"FLAME Hub deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/hub-introduction.md","filePath":"guide/deployment/hub-introduction.md"}'),i={name:"guide/deployment/hub-introduction.md"};function n(l,e,s,h,d,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="flame-hub-deployment" tabindex="-1">FLAME Hub deployment <a class="header-anchor" href="#flame-hub-deployment" aria-label="Permalink to &quot;FLAME Hub deployment&quot;">​</a></h1><p>This section describes a standalone FLAME Hub deployment. The supported production path is the <a href="https://github.com/PrivateAIM/helm/tree/master/charts/flame-hub" target="_blank" rel="noreferrer">FLAME Hub Helm chart</a> on Kubernetes. Docker Compose is available for development and evaluation, but it does not include Harbor and is not the recommended production topology.</p><h2 id="what-the-chart-installs" tabindex="-1">What the chart installs <a class="header-anchor" href="#what-the-chart-installs" aria-label="Permalink to &quot;What the chart installs&quot;">​</a></h2><p>The Hub chart installs the FLAME services and their supporting components, including:</p><ul><li>Core FLAME Hub services</li><li>Databases, S3 Storage, Message Broker</li><li>Harbor for storing container images (optional, you can also bring your own)</li><li>Ingress or HTTPRoute/Gateway, but <strong>no Ingress controller or Gateway Controller</strong></li></ul><h2 id="baseline-requirements" tabindex="-1">Baseline requirements <a class="header-anchor" href="#baseline-requirements" aria-label="Permalink to &quot;Baseline requirements&quot;">​</a></h2><ul><li>A supported Kubernetes cluster and Helm 3.</li><li>A default <code>StorageClass</code>, or explicit storage classes for every persistent component.</li><li>At least 4 CPU cores and enough memory and storage for the enabled services. Capacity depends on the number and size of analyses; the worker and registry volumes usually dominate.</li><li>A DNS name for the Hub. If the bundled Harbor registry is enabled, it needs a separate hostname.</li><li>An Ingress controller or a Gateway API implementation. The chart is tested with NGINX Gateway Fabric when using Gateway API.</li><li>TLS certificates for every public hostname in a real deployment.</li></ul><p>For an OpenStack-hosted cluster, use the OpenStack Cinder CSI driver and a suitable Cinder <code>StorageClass</code>. Cinder/Ceph supplies durable, reattachable block storage.</p><h2 id="repository-responsibilities" tabindex="-1">Repository responsibilities <a class="header-anchor" href="#repository-responsibilities" aria-label="Permalink to &quot;Repository responsibilities&quot;">​</a></h2><ul><li>This documentation repository owns the deployment concepts and complete guides.</li><li><a href="https://github.com/PrivateAIM/hub-deployment" target="_blank" rel="noreferrer"><code>PrivateAIM/hub-deployment</code></a> contains small helper scripts, copyable configuration snippets and the docker-compose file.</li><li><a href="https://github.com/PrivateAIM/helm" target="_blank" rel="noreferrer"><code>PrivateAIM/helm</code></a> owns the chart, default values, and the exhaustive value reference.</li></ul><p>Continue with <a href="./microk8s-quickstart.html">Kubernetes preparation</a> or go directly to <a href="./hub-installation.html">installing the Hub chart</a> if a cluster is already available.</p>',11)]))}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
